AtlasUtil = {}

function AtlasUtil:Unpack(atlas)
	assert(atlas, "Usage: AtlasUtil:Unpack(atlasName). Got 'nil' for argument")
	local info = AtlasInfo[atlas] or AtlasInfo[atlas:lower()]
	assert(info, "AtlasUtil:Unpack("..atlas..") Atlas does not exist")

	return unpack(info)
end

function AtlasUtil:GetAtlasInfo(atlas)
	local texture, width, height, left, right, top, bottom, tileH, tileV = self:Unpack(atlas)
	return {
		width = width,
		height = height,
		leftTexCoord = left,
		rightTexCoord = right,
		topTexCoord = top,
		bottomTexCoord = bottom,
		tilesHorizontally = tileH,
		tilesVertically = tileV,
		filename = texture,
	}
end

function AtlasUtil:GetCoords(atlas)
	local _, _, _, left, right, top, bottom = self:Unpack(atlas)
	return left, right, top, bottom
end

function AtlasUtil:AtlasExists(atlas)
	if not atlas then return false end
	return AtlasInfo[atlas] ~= nil or AtlasInfo[atlas:lower()] ~= nil
end

function AtlasUtil:GetSize(atlas)
	if not atlas then return 0, 0 end
	local info = AtlasInfo[atlas] or AtlasInfo[atlas:lower()]

	if not info then return 0, 0 end
	return info[2], info[3]
end

local SecureFrame = CreateFrame("Frame")
SecureFrame:SetScript("OnAttributeChanged", function(self, attribute, value)
    if attribute == "add-atlas" then
        local info = {
            self:GetAttribute("texture"),
            tonumber(self:GetAttribute("sizeX")),
            tonumber(self:GetAttribute("sizeY")),
            tonumber(self:GetAttribute("left")),
            tonumber(self:GetAttribute("right")),
            tonumber(self:GetAttribute("top")),
            tonumber(self:GetAttribute("bottom")),
            self:GetAttribute("horizTile"),
            self:GetAttribute("vertTile"),
        }
        AtlasInfo[self:GetAttribute("name")] = info
    end
end)

function AtlasUtil:AddAtlas(name, texture, sizeX, sizeY, left, right, top, bottom, horizTile, vertTile)
    if not name or AtlasInfo[name] then
        return
    end

    SecureFrame:SetAttribute("name", name)
    SecureFrame:SetAttribute("texture", texture)
    SecureFrame:SetAttribute("sizeX", sizeX)
    SecureFrame:SetAttribute("sizeY", sizeY)
    SecureFrame:SetAttribute("left", left)
    SecureFrame:SetAttribute("right", right)
    SecureFrame:SetAttribute("top", top)
    SecureFrame:SetAttribute("bottom", bottom)
    SecureFrame:SetAttribute("horizTile", horizTile)
    SecureFrame:SetAttribute("vertTile", vertTile)
    SecureFrame:SetAttribute("add-atlas", true)
end

